apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: {{hpa_name}}
  namespace: {{namespace}}
spec:
  scaleTargetRef:
    apiVersion: apps/v1
    kind: Deployment
    name: {{target_deployment}}
  minReplicas: {{min_replicas}}
  maxReplicas: {{max_replicas}}
  metrics:
    - type: Resource
      resource:
        name: cpu
        target:
          type: Utilization
          averageUtilization: {{cpu_target_percent}}
